import copy
def restore(request,case,backup):
    code,owner=request('GET',case['owner_path'])
    if code!=200 or owner['metadata']['uid']!=case['owner_uid']:raise ValueError('approved owner identity changed')
    if backup['metadata']['uid']!=case['lost_uid'] or backup['metadata']['namespace']!=case['lost_namespace']:raise ValueError('backup is not the approved lost object')
    reference=dict(apiVersion=owner['apiVersion'],kind=owner['kind'],name=owner['metadata']['name'],uid=owner['metadata']['uid'],controller=True)
    metadata=dict(name=backup['metadata']['name'],namespace=owner['metadata']['namespace'],labels=copy.deepcopy(backup['metadata'].get('labels',{})),ownerReferences=[reference])
    body=dict(apiVersion='v1',kind='Secret',metadata=metadata,type=backup['type'],data=copy.deepcopy(backup['data']))
    code,result=request('POST','/api/v1/namespaces/'+owner['metadata']['namespace']+'/secrets',body)
    if code!=201:raise RuntimeError('approved same-namespace restore failed')
    return result['metadata']['uid']

